import { renderTravelReference } from './status-reference.js';
import { travelEnergyView, campingActions } from './travel-energy.js';
import { getActions, getLifeCommitment } from './engine.js';
import { travelView, travelRouteOptions } from './travel.js';
import { ROAD_PREFERENCES, roadPreference } from './road-routes.js';

export function renderRoadPlanPanel(s,ui,{destinationId=null}={}){
 if(!s.travel)return '';
 if(s.trail){const v=travelEnergyView(s);return `<section class="travel-energy-summary" data-travel-energy><strong>Focus ${s.hero.mp}/${s.hero.maxMp}</strong><p>${ui.e(v.summary)}</p><small>Travel and spells use the same Focus. Camp to recover; shelter packs have limited nights. No road preparations or departure fee.</small></section>`;}
 const {e}=ui,v=travelView(s),p=v.plan,selected=roadPreference(s.travel.routePreference),commit=getLifeCommitment(s);
 const locked=!!(s.event||s.battle||s.conversations?.pending||s.dungeon||commit||s.workshop?.project||s.careers?.batch||s.life?.plan||s.phase==='retired'||s.cartography?.offsite);
 const options=destinationId?travelRouteOptions(s,destinationId):null,place=id=>s.world.locations.find(p=>p.id===id)?.name||id;
 const routes=options?`<div class="road-route-options" role="group" aria-label="Compare open road routes">${options.map(({id,label,preview:q})=>`<label class="road-route-option ${id===selected?'selected':''}"><input type="radio" name="routePreference" value="${id}" ${id===selected?'checked':''}><span><strong>${e(label)}</strong><span>${q.days} days · ${q.cost}g departure preparations</span><span>${q.risk}% highest leg danger · ${q.exposure} exposure points across ${q.checks} check${q.checks===1?'':'s'}</span><small>${e(q.route.map(place).join(' → ')||'No open road')}</small></span></label>`).join('')}</div><p class="small-copy">Exposure points add the leg danger percentages. Each leg receives its own check; the total is not a whole-journey percentage. Routes can coincide where the roads offer the same best path.</p>`:`<label class="field">Route preference<select name="routePreference">${ROAD_PREFERENCES.map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${e(label)}</option>`).join('')}</select></label>`;
 const quote=options?.find(row=>row.id===selected)?.preview,notes=quote?`${ui.livingCosts?.(quote.days)||''}<details class="spatial-details" data-disclosure="saved-road-details"><summary>Saved route details and safeguards</summary>${quote.legs.map(leg=>`<p class="small-copy">${e(place(leg.from))} → ${e(place(leg.to))} · ${leg.totalDays} days · ${leg.risk}% danger check</p>`).join('')}${quote.precautions.map(copy=>`<p class="small-copy">${e(copy)}</p>`).join('')}</details>`:'';
 return `<section class="panel travel-plan" data-road-plan><div class="eyebrow">BEFORE DEPARTURE</div><h3>${destinationId?`Road preparations for ${e(place(destinationId))}`:'Prepare for the road'}</h3><p class="small-copy">${e(v.summary)}</p><form id="travel-plan-form"><fieldset ${locked?'disabled':''}>${routes}<label class="field">Travel pace<select name="pace">${[['steady','Steady'],['cautious','Cautious · longer, safer'],['fast','Fast · shorter, riskier']].map(([id,label])=>`<option value="${id}" ${p.pace===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="travel-options">${[['supplies','Packed provisions','Paid departure supplies reduce danger; these are separate from dungeon rations.'],['scout','Scout the road','Two gold and one preparation day on the first leg.'],['escort','Hire an escort','Reduces danger; the fee follows the actual number of road legs.'],['night','Travel after dusk','Avoid daylight exposure, with slightly higher road danger.']].map(([key,label,copy])=>`<label><input type="checkbox" name="${key}" ${p[key]?'checked':''}><span><strong>${label}</strong><small>${copy}</small></span></label>`).join('')}</div><p class="small-copy" data-road-draft hidden role="status">Save these changes to refresh the route quotes before departing.</p><button class="button secondary" type="submit">Save preparations and refresh quotes</button></fieldset></form><p class="small-copy">${locked?'Finish the present decision or commitment before changing preparations.':'Saving spends no day or gold. The quotes and departure use your saved preparations.'}</p>${notes}</section>`;
}
export function roadJourneyProgress(s){
 const j=s.timeline?.journey;if(!j)return null;
 const legs=j.route.slice(1).map((to,i)=>{const from=j.route[i],road=s.world.roads.find(r=>r.from===from&&r.to===to||r.from===to&&r.to===from);return {from,to,totalDays:j.legs?.[i]?.totalDays??road?.days??1,checked:j.legs?.[i]?.checked===true};});
 const total=legs.reduce((n,l)=>n+l.totalDays,0),completed=legs.reduce((n,l,i)=>n+(i<j.legIndex?l.totalDays:i===j.legIndex?j.legProgress:0),0);
 return {destinationId:j.destinationId,legs,total,completed,remaining:Math.max(0,total-completed),departureCost:j.departureCost??null,responseDays:s.travel?.pending?.stage==='delay'?s.travel.pending.remainingDays:0};
}
export function renderRoadJourney(s,ui){
 const v=roadJourneyProgress(s);if(!v)return '';
 const {e,actionCards}=ui,j=s.timeline.journey,name=id=>s.world.locations.find(p=>p.id===id)?.name||id,actions=getActions(s).filter(a=>a.id==='grow_continue_journey'||a.id==='travel_continue_response'||a.id==='trail_camp');
 if(j.energyVersion===1){const energy=travelEnergyView(s);return `<section class="panel journey-panel" data-road-journey><span class="eyebrow">ON THE ROAD</span><h2>${e(name(v.destinationId))}</h2><p>${e(name(j.route[j.legIndex]))} → ${e(name(j.route[j.legIndex+1]))} · ${v.remaining} normal days of distance remain${j.energyStep?` · This stretch: ${j.energyStep.progress}/${j.energyStep.totalDays} days`:''}</p><p><strong>Focus ${energy.focus}/${energy.max}</strong> · ${energy.days} travel days since rest</p><p>${e(energy.summary)}</p>${energy.focus===0?'<p class="disabled-reason">Continuing exhausted can be fatal. Make camp before walking further.</p>':''}${renderTravelReference(s,ui,{legacy:false,days:null,fee:j.departureCost,paid:true,camp:actions.find(a=>a.id==='trail_camp'),key:'today-travel-reference'})}${actions.length?actionCards(actions):'<p>Resolve the current encounter, then continue or camp.</p>'}</section>`;}
 return `<section class="panel journey-panel" data-road-journey><div class="eyebrow">YOUR SAVED ROAD JOURNEY</div><h2>On the road to ${e(name(v.destinationId))}</h2><p>${v.completed}/${v.total} planned road days completed · ${v.remaining} remain.${v.responseDays?` Another ${v.responseDays} attended response day remains.`:''}${v.departureCost!==null?` ${v.departureCost} gold already committed.`:''}</p><div class="saved-road-legs">${v.legs.map((l,i)=>`<p><strong>${e(name(l.from))} → ${e(name(l.to))}</strong><span>${i<j.legIndex?'Complete':i===j.legIndex?`${j.legProgress}/${l.totalDays} days`:`${l.totalDays} days`}${l.checked?' · encounter checked':''}</span></p>`).join('')}</div>${renderTravelReference(s,ui,{legacy:true,days:v.remaining+v.responseDays,fee:j.departureCost,paid:true,camp:actions.find(a=>a.id==='trail_camp'),key:'today-travel-reference'})}<p class="small-copy">Responses and calendar needs keep their own time. Continuing uses the saved route, attended days and departure payment.</p>${actions.length?actionCards(actions):'<p class="small-copy">Finish the present road or calendar decision here, then continue this same journey.</p>'}</section>`;
}
